// === Tab: CardioidClass ===
class Cardioid {
  constructor( newX, newY, pNumberPoints, newR, factor) {
    this.numOfPoints = pNumberPoints;
    this.angle = 2*PI/this.numOfPoints;
    this.arrayOfPointsOnCircle =[];
    this.r = newR;
    this.x = newX;
    this.y = newY;
    this.factor = factor;
    this.index = 0;
    noFill();
  }

  makeArrayOfPoints() {
    let posArrayPoints =0;
    for (let i = 0; i<this.numOfPoints; i++) {
      let xCoord = this.x + this.r*cos(i*this.angle+PI);
      let yCoord = this.y + this.r*sin(i*this.angle+PI);
      let v = new p5.Vector(xCoord, yCoord);
      this.arrayOfPointsOnCircle.push(v) ;
    }
  }

  drawPoints() {
    noFill();
    beginShape();
    for ( let point of this.arrayOfPointsOnCircle) {
      vertex(point.x, point.y);
    }
    endShape(CLOSE);
  }

  drawLinesBetweenPoints() {
    stroke(this.factor*100 % 360, 100, 100);
    ellipse (this.x, this.y, 2*this.r);

    if (this.index < this.arrayOfPointsOnCircle.length) {
      line(this.arrayOfPointsOnCircle[this.index].x, this.arrayOfPointsOnCircle[this.index].y, this.arrayOfPointsOnCircle[(this.index*this.factor)%this.numOfPoints].x, this.arrayOfPointsOnCircle[(this.index*this.factor)%this.numOfPoints].y);
      this.index++;
    }
  }
}


