let cardioArray = [];
let numPoints ;
const radius = 100;


function setup() {
  createCanvas(1200, 800);
  colorMode(HSB, 360, 100, 100);
  background(0,0,0, 50);
  strokeWeight(1);
  let groesse = 2*radius;
  let gap = 20;
  numPoints = 250;
  for (let i=0; i<10; i++) {
    //Cardioid(float newX, float newY, int , int newR);
    cardioArray.push(new Cardioid((groesse+gap)*(i%5)+gap + radius, floor(i/5)*(gap+2*radius)+gap+radius, numPoints, radius, i+2));
    }

  for (let i=0; i<cardioArray.length; i++) {
    cardioArray[i].makeArrayOfPoints();
    cardioArray[i].drawPoints();
  }
}

function draw() {
  for (let i=0; i<cardioArray.length; i++) {
    cardioArray[i].drawLinesBetweenPoints();
  }
}
